package dustin.cex.domains.kyc;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import dustin.cex.domains.travelrule.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.core.env.MapPropertySource;
import org.springframework.transaction.support.TransactionTemplate;

/** 실제 보류 원장/현재 고객 확인에서 일정·제공 의도·실행·암호화 응답을 연결한다. 외부 HTTP만 대역으로 둔다. */
class CodeVaspTransferProcessingIntegrationTest extends CodeVaspTransferTestSupport {
    CodeVaspSettings ownSettings;CodeVaspDirectoryService ownDirectory;CodeVaspDepositSearches ownSearches;CodeVaspDepositSearches.Search target;CodeVaspTransferIntents ownIntents;CodeVaspTransferExecution ownExecution;CodeVaspTransferProcessing processing;
    @BeforeEach void scope(){
        // 금융 이력을 삭제하지 않고 각 시험의 접속 주체를 분리한다. 다른 시험의 FOUND 입금이 자동 선택되지 않는다.
        ownSettings=new CodeVaspSettings("http://127.0.0.1:1","http://127.0.0.1:2","automatic-"+UUID.randomUUID(),KEY);ownDirectory=new CodeVaspDirectoryService(ownSettings,directoryClient,jdbc,json,audit,manager);ownDirectory.refresh();ownSearches=new CodeVaspDepositSearches(ownDirectory,jdbc,audit,manager);target=ownSearches.reserve(receipt.id());found(target);
        ownIntents=new CodeVaspTransferIntents(ownSearches,new CodeVaspDepositSearchExecution(ownSearches,transactions,jdbc,audit,json,manager),ownDirectory,policy(),users,eligibility,crypto,jdbc,json,audit,manager,purposes);ownExecution=new CodeVaspTransferExecution(ownIntents,transfers,crypto,jdbc,json,audit,manager,assessments);processing=new CodeVaspTransferProcessing(ownDirectory,ownIntents,ownExecution,jdbc,audit,manager);
        doAnswer(call->{CodeVaspTransferDataClient.Request r=call.getArgument(0);var person=new CodeVaspTransferDataClient.Person(r.recipientName(),null,LocalDate.of(1990,1,1),List.of(r.query().beneficiaryAddress()));return new CodeVaspTransferDataClient.Result("NORMAL",null,new CodeVaspTransferDataClient.Data(r.query().requestId(),r.peer().entityId(),r.expectedAddressAmount(),person,person,"b".repeat(64)));}).when(transfers).exchange(any());clearInvocations(directoryClient);
    }
    Map<String,Object> job(){return jdbc.queryForMap("SELECT * FROM codevasp_transfer_jobs WHERE search_id=?",target.id());}
    void noMoreIo(){clearInvocations(transfers);}
    @Test void foundPendingAutomaticallyReservesTransfersAndFinishesOnce(){var report=processing.processNext().orElseThrow();assertEquals(target.id(),report.searchId());assertEquals("DONE",report.status());assertEquals("DATA_RECEIVED",ownExecution.current(report.intentId()).status());assertTrue(processing.processNext().isEmpty());assertNull(job().get("lease_id"));assertNull(job().get("next_attempt_at"));org.mockito.Mockito.verify(transfers,times(1)).exchange(any());noMoreIo();}
    @Test void heldReceiptDoesNotBlockAnotherReadyDeposit(){BitcoinDepositFixtures.observe(jdbc,json,manager,qualification,receipt,true);assertEquals("HELD",processing.processNext().orElseThrow().status());var another=BitcoinDepositFixtures.seed(jdbc,json,customer.getId(),Instant.now());BitcoinDepositFixtures.observe(jdbc,json,manager,qualification,another,false);pending.recognize(another.id());var second=ownSearches.reserve(another.id());found(second);var report=processing.processNext().orElseThrow();assertEquals(second.id(),report.searchId());assertEquals("DONE",report.status());assertEquals("HELD",job().get("state"));org.mockito.Mockito.verify(transfers,times(1)).exchange(any());noMoreIo();}
    @Test void provenNonSendSchedulesRetryInsteadOfRepeatingImmediately(){doThrow(new CodeVaspSubmissionFailure(CodeVaspSubmissionFailure.Admission.NOT_SENT)).when(transfers).exchange(any());var report=processing.processNext().orElseThrow();assertEquals("RETRY",report.status());assertEquals("NOT_SENT",job().get("last_reason"));assertTrue(processing.processNext().isEmpty());assertTrue(jdbc.queryForObject("SELECT next_attempt_at>=updated_at+interval '119 seconds' FROM codevasp_transfer_jobs WHERE search_id=?",Boolean.class,target.id()));org.mockito.Mockito.verify(transfers,times(1)).exchange(any());noMoreIo();}
    @Test void unknownOutcomeStopsAutomaticProcessingForReview(){doThrow(new CodeVaspSubmissionFailure(CodeVaspSubmissionFailure.Admission.OUTCOME_UNKNOWN)).when(transfers).exchange(any());assertEquals("REVIEW_REQUIRED",processing.processNext().orElseThrow().status());assertNull(job().get("next_attempt_at"));assertTrue(processing.processNext().isEmpty());org.mockito.Mockito.verify(transfers,times(1)).exchange(any());noMoreIo();}
    @Test void failedExecutionFinishAuditBecomesUnresolvedReviewWithoutRepeat(){doThrow(new IllegalStateException("격리 실행 완료 감사 장애")).when(audit).record(isNull(),eq("CODE_TRANSFER_FINISHED"),anyString(),anyString(),anyString());var report=processing.processNext().orElseThrow();assertEquals("REVIEW_REQUIRED",report.status());assertEquals("RUNNING",report.failureCode());assertEquals("RUNNING",ownExecution.current(report.intentId()).status());assertTrue(processing.processNext().isEmpty());org.mockito.Mockito.verify(transfers,times(1)).exchange(any());noMoreIo();}
    @Test void jobFinishFailureRecoversFromDurableReplyWithoutAnotherPut(){doThrow(new IllegalStateException("격리 일정 완료 감사 장애")).when(audit).record(isNull(),eq("CODE_TRANSFER_JOB_FINISHED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,processing::processNext);assertNotNull(job().get("lease_id"));assertTrue(processing.processNext().isEmpty());doCallRealMethod().when(audit).record(isNull(),eq("CODE_TRANSFER_JOB_FINISHED"),anyString(),anyString(),anyString());jdbc.update("UPDATE codevasp_transfer_jobs SET lease_until=clock_timestamp()-interval '1 second' WHERE search_id=?",target.id());assertEquals("DONE",processing.processNext().orElseThrow().status());org.mockito.Mockito.verify(transfers,times(1)).exchange(any());noMoreIo();}
    @Test void claimAuditFailureRollsBackSeedAndLeaseBeforeAnyDisclosure(){doThrow(new IllegalStateException("격리 일정 시작 감사 장애")).when(audit).record(isNull(),eq("CODE_TRANSFER_JOB_CLAIMED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,processing::processNext);assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM codevasp_transfer_jobs WHERE search_id=?",Long.class,target.id()));org.mockito.Mockito.verifyNoInteractions(transfers);}
    @Test void expiredLeaseReplacementCannotBeOverwrittenByLateCompletion(){
        doAnswer(call->{jdbc.update("UPDATE codevasp_transfer_jobs SET lease_until=clock_timestamp()-interval '1 second' WHERE search_id=?",target.id());var replacement=processing.processNext().orElseThrow();assertEquals("REVIEW_REQUIRED",replacement.status());CodeVaspTransferDataClient.Request r=call.getArgument(0);var person=new CodeVaspTransferDataClient.Person(r.recipientName(),null,LocalDate.of(1990,1,1),List.of(receipt.address()));return new CodeVaspTransferDataClient.Result("NORMAL",null,new CodeVaspTransferDataClient.Data(r.query().requestId(),"origin",r.expectedAddressAmount(),person,person,"b".repeat(64)));}).when(transfers).exchange(any());
        assertTrue(processing.processNext().isEmpty());assertEquals("REVIEW_REQUIRED",job().get("state"));assertEquals("DATA_RECEIVED",ownExecution.current((UUID)jdbc.queryForMap("SELECT id FROM codevasp_transfer_intents WHERE search_id=?",target.id()).get("id")).status());org.mockito.Mockito.verify(transfers,times(1)).exchange(any());noMoreIo();
    }
    @Test void customerHoldCanBeRecheckedAfterMutableScheduleBecomesDue(){jdbc.update("UPDATE users SET trading_restricted=true WHERE id=?",customer.getId());assertEquals("HELD",processing.processNext().orElseThrow().status());org.mockito.Mockito.verifyNoInteractions(transfers);jdbc.update("UPDATE users SET trading_restricted=false WHERE id=?",customer.getId());jdbc.update("UPDATE codevasp_transfer_jobs SET next_attempt_at=clock_timestamp() WHERE search_id=?",target.id());assertEquals("DONE",processing.processNext().orElseThrow().status());org.mockito.Mockito.verify(transfers,times(1)).exchange(any());noMoreIo();}
    @Test void latestNonFoundSearchCannotSeedPrivateJob(){when(transactions.result(target.id())).thenThrow(new IllegalStateException("격리 최신 검색 실패"));new CodeVaspDepositSearchExecution(ownSearches,transactions,jdbc,audit,json,manager).refresh(target.id());clearInvocations(transactions);assertTrue(processing.processNext().isEmpty());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM codevasp_transfer_jobs WHERE search_id=?",Long.class,target.id()));org.mockito.Mockito.verifyNoInteractions(transfers);}
    @Test void ambientTransactionCannotSeedClaimOrDisclose(){assertThrows(IllegalStateException.class,()->new TransactionTemplate(manager).execute(t->processing.processNext()));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM codevasp_transfer_jobs WHERE search_id=?",Long.class,target.id()));org.mockito.Mockito.verifyNoInteractions(transfers);}
    @Test void ownedProductionWorkerRunsRealProcessingAndCloses(){try(var context=new AnnotationConfigApplicationContext()){context.getEnvironment().setActiveProfiles("production");context.getEnvironment().getPropertySources().addFirst(new MapPropertySource("격리 자동 정보 교환",Map.of("codevasp.processing.enabled","true","codevasp.private-transfer.enabled","true")));context.registerBean("codeVaspSchemaInitializer",Object.class,Object::new);context.registerBean(CodeVaspSettings.class,()->ownSettings);context.registerBean(CodeVaspTransferProcessing.class,()->processing);context.register(CodeVaspTransferWorker.class);context.refresh();org.awaitility.Awaitility.await().atMost(Duration.ofSeconds(4)).untilAsserted(()->assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM codevasp_transfer_jobs WHERE search_id=? AND state='DONE'",Long.class,target.id())));}org.mockito.Mockito.verify(transfers,times(1)).exchange(any());noMoreIo();}
    @Test void scheduleCannotClaimDoneWithoutReplyOrLoseItsSource(){jdbc.update("UPDATE users SET trading_restricted=true WHERE id=?",customer.getId());assertEquals("HELD",processing.processNext().orElseThrow().status());var failure=assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("UPDATE codevasp_transfer_jobs SET state='DONE',next_attempt_at=NULL WHERE search_id=?",target.id()));assertTrue(failure.getMostSpecificCause().getMessage().contains("수신 원본 없이 정보 교환 작업을 완료할 수 없습니다"));assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.execute("DELETE FROM codevasp_transfer_jobs WHERE search_id='"+target.id()+"'"));assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.execute("TRUNCATE codevasp_transfer_jobs"));assertEquals("HELD",job().get("state"));org.mockito.Mockito.verifyNoInteractions(transfers);}
    @Test void anotherConnectionAuthorityCannotClaimExistingJob(){jdbc.update("UPDATE users SET trading_restricted=true WHERE id=?",customer.getId());assertEquals("HELD",processing.processNext().orElseThrow().status());var other=new CodeVaspDirectoryService(new CodeVaspSettings("http://127.0.0.1:1","http://127.0.0.1:2","unrelated-"+UUID.randomUUID(),KEY),directoryClient,jdbc,json,audit,manager);assertTrue(new CodeVaspTransferProcessing(other,ownIntents,ownExecution,jdbc,audit,manager).processNext().isEmpty());assertEquals("HELD",job().get("state"));org.mockito.Mockito.verifyNoInteractions(transfers);}

    /** 새 접속 주체로 미평가/소액 입금만 선택한다. 앞선 정상 입금의 자동 작업과 섞지 않는다. */
    void purposeRestrictedReceipt(boolean valued){
        if(valued)publishPrice("8100000.00000000");
        else {doThrow(new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE,"격리 가격 부재")).when(priceClient).read();assertEquals("FAILED",prices.refresh().status());}
        receipt=BitcoinDepositFixtures.seed(jdbc,json,customer.getId(),Instant.now());
        BitcoinDepositFixtures.observe(jdbc,json,manager,qualification,receipt,false);pending.recognize(receipt.id());
        clearInvocations(priceClient);scope();
    }
    @Test void smallReferenceRequiresReviewWithoutPrivateRequestOrAutomaticRetry(){
        purposeRestrictedReceipt(true);var report=processing.processNext().orElseThrow();assertEquals("REVIEW_REQUIRED",report.status());assertEquals("CURRENT_CONDITIONS_NOT_MET",report.failureCode());assertNull(report.intentId());assertNull(job().get("next_attempt_at"));assertTrue(processing.processNext().isEmpty());org.mockito.Mockito.verifyNoInteractions(transfers,priceClient);
    }
    @Test void missingValuationRequiresReviewWithoutPrivateRequestOrAutomaticRetry(){
        purposeRestrictedReceipt(false);var report=processing.processNext().orElseThrow();assertEquals("REVIEW_REQUIRED",report.status());assertNull(report.intentId());assertNull(job().get("next_attempt_at"));assertTrue(processing.processNext().isEmpty());org.mockito.Mockito.verifyNoInteractions(transfers,priceClient);
    }
}
